SELECT
  CASE
    WHEN m.id IS NULL THEN 'Não'
    ELSE 'Sim'
  END AS lead_existe,

  CASE
    WHEN m.id IS NULL THEN NULL
    WHEN m.lixeira = 1 THEN 'Sim'
    ELSE 'Não'
  END AS esta_na_lixeira,

  CASE
    WHEN m.id IS NULL THEN NULL
    WHEN EXISTS (
      SELECT 1
      FROM operacao o
      WHERE o.mailing_id = m.id
    )
    THEN 'Sim'
    ELSE 'Não'
  END AS tem_operacao,

  m.id AS mailing_id,
  m.clientes,
  m.empresa,
  m.whatsapp,
  m.status_contato,
  m.status_plano_acao,
  m.fup,

  CASE
    WHEN m.id IS NULL THEN 'Não'
    WHEN m.fup IS NULL OR m.fup = '' THEN 'Sim'
    WHEN DATE(m.fup) < CURDATE() THEN 'Sim'
    ELSE 'Não'
  END AS alterar_fup,

  m.email

FROM (SELECT 1) base

LEFT JOIN (
  SELECT *
  FROM mailing
  WHERE whatsapp IN (

"{{ 
(() => {
  const raw = String($('Webhook').first().json.body.sender.phone_number || '');

  let phone = raw.replace(/\D/g, '');

  if (phone.startsWith('55')) phone = phone.slice(2);

  const ddd = phone.slice(0,2);
  const numero = phone.slice(2);

  const com9 = numero.length === 8
    ? '9' + numero
    : numero;

  return com9.length === 9
    ? `(${ddd}) ${com9.slice(0,5)}-${com9.slice(5)}`
    : `(${ddd}) ${com9.slice(0,4)}-${com9.slice(4)}`;
})()
}}",

"{{ 
(() => {
  const raw = String($('Webhook').first().json.body.sender.phone_number || '');

  let phone = raw.replace(/\D/g, '');

  if (phone.startsWith('55')) phone = phone.slice(2);

  const ddd = phone.slice(0,2);
  const numero = phone.slice(2);

  const sem9 = numero.length === 9 && numero.startsWith('9')
    ? numero.slice(1)
    : numero;

  return `(${ddd}) ${sem9.slice(0,4)}-${sem9.slice(4)}`;
})()
}}"

)
  ORDER BY id DESC
  LIMIT 1
) m ON 1 = 1;

